week_total = 7_000_000
user_calls = {'월': 120, '화': 100, '수': 100, '목': 100, '금': 110, '토': 60, '일': 60}
inv = {d: 1 / v for d, v in user_calls.items()}
s = sum(inv.values())
plan = {d: int(week_total * w / s) for d, w in inv.items()}
plan['일'] += week_total - sum(plan.values())
print(plan, '합', sum(plan.values()))
per_min = plan['월'] // (6 * 60)
print('월요일 1분당', per_min, '명 -> 100ms 칸당 약', per_min // 600, '명')
